import {caseArchitecture} from './architecture.js?v=20260918-topology';
import {companyPlaybook,companyStories} from './company-playbooks.js';
import {vendorConfig} from './vendor-config.js?v=20260920-live2';
import {cases} from './workshop.js';
import {lenaNarrative} from './journey-narrative.js?v=20260919-journeys1';
const e=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const orders=[
 {id:'WO-2048',property:'Harbor View',title:'Prepare the guest-room welcome packs',area:'Guest services · 120 rooms',status:'Ready to schedule',due:'Before arrival',detail:'Coordinate delivery with the property contact and confirm the approved room count. This illustrative order belongs to the sample vendor company.'},
 {id:'WO-2051',property:'Bayside',title:'Replace lobby information displays',area:'Front office · 8 displays',status:'Awaiting confirmation',due:'Next service visit',detail:'Review display specifications with the front-office team before booking a service visit. This is synthetic workshop data.'},
 {id:'WO-2057',property:'Harbor View',title:'Confirm seasonal amenities delivery',area:'Receiving · 24 cartons',status:'In progress',due:'This engagement',detail:'Check the sample delivery manifest and contact the property coordinator about outstanding items. No real order or supplier system is connected.'}
];
const stages=[
 ['Discover','Lena arrives at a recognizable Harborline experience','Start with the business task, brand and consent boundary. The customer should understand where she is before learning anything about the tenant architecture.'],
 ['Register','External ID creates or finds Lena’s identity','The configured flow offers eligible methods, collects only approved attributes and handles duplicate or returning users deliberately.'],
 ['Establish trust','Harborline decides which identity provider to trust','A local account, social identity or enterprise federation can establish identity. Issuer, subject and assurance remain explicit inputs to the application.'],
 ['Authorize','Resolve company, role and property scope','A trusted application data store maps the authenticated subject to approved business relationships. Self-entered company information is not an entitlement.'],
 ['Encounter risk','Challenge or deny a higher-risk action','Conditional Access, MFA and application transaction controls should respond to the real risk and supported External ID capabilities.'],
 ['Recover','Return Lena to useful access safely','The prepared recovery path verifies the intended account, records the outcome and returns Lena to the application without exposing credentials.'],
 ['Change or leave','Update or remove the business relationship','Profile changes, vendor reassignment, expiration and deletion need owners, effective dates and application-side cleanup.'],
 ['Prove','Connect the experience to actual records','Match the user, application, timestamp and result in External ID logs, then use application audit records to prove the allowed or denied business action.']
];
let view='experience',scene='welcome',selectedOrder=null,explainIndex=0,checked=new Set();
const proof=[
 ['Registration','Show the configured user flow and Lena’s resulting account in the external tenant.'],
 ['Authentication','Show the actual sign-in event, application, authentication details and result.'],
 ['Business context','Show the trusted mapping between the authenticated subject, company and permitted properties.'],
 ['Authorization','Test an allowed work order and a denied cross-company request against the server/API.'],
 ['Recovery','For the prepared local password account, observe the real recovery flow and a successful follow-up sign-in.']
];
function liveLink(label){return vendorConfig.livePortalUrl?`<a class="primary" href="${e(vendorConfig.livePortalUrl)}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`:`<button class="outline" disabled title="The live vendor application URL has not been verified">Live sign-in · connection pending</button>`;}
function identityConstellation(){return `<div class="external-constellation" aria-label="External ID experience map"><svg viewBox="0 0 520 300" aria-hidden="true"><defs><linearGradient id="external-line" x1="0" x2="1"><stop stop-color="#20f593"/><stop offset="1" stop-color="#b98aff"/></linearGradient></defs><path d="M260 150 92 74M260 150 428 74M260 150 92 230M260 150 428 230"/><circle cx="260" cy="150" r="72"/><circle cx="260" cy="150" r="105"/></svg><div class="external-core"><small>EXTERNAL ID</small><strong>LF</strong><span>Lena Fischer</span></div><div class="external-node n1"><b>01</b><span>Branded<br>sign-up</span></div><div class="external-node n2"><b>02</b><span>Trusted<br>identity</span></div><div class="external-node n3"><b>03</b><span>Application<br>role</span></div><div class="external-node n4"><b>04</b><span>Allowed<br>work</span></div><div class="external-orbit-label">IDENTITY → CONTEXT → AUTHORIZATION → EVIDENCE</div></div>`;}
function vendorJourney(){const active=view==='experience'?scene==='welcome'?0:1:view==='explain'?explainIndex:7;return `<div class="vendor-journey" aria-label="Lena’s External ID lifecycle"><span>EXTERNAL ID JOURNEY</span>${stages.map((s,i)=>`<button data-vendor="journey" data-index="${i}" class="${i===active?'active':''}" ${i===active?'aria-current="step"':''}><b>0${i+1}</b><small>${e(s[0])}</small></button>`).join('')}</div>`;}
function vendorNarrative(){return `<section class="vendor-narrative"><div><span class="vendor-kicker">BUSINESS OUTCOME</span><h3>${e(lenaNarrative.outcome)}</h3><p>${e(lenaNarrative.owner)}</p></div><details><summary>Deployment, customization, AI and replay <i>+</i></summary><div class="vendor-narrative-grid"><section><span class="vendor-kicker">CUSTOMIZE THE JOURNEY</span><ul>${lenaNarrative.customizations.map(x=>`<li>${e(x)}</li>`).join('')}</ul></section><section><span class="vendor-kicker">HOW AI HELPS</span><p>${e(lenaNarrative.ai)}</p></section><section><span class="vendor-kicker">RESET &amp; REPLAY</span><p>${e(lenaNarrative.reset)}</p></section></div></details></section>`;}
function experience(){return `<div class="vendor-preview-note live"><span>LIVE SUPPLIER DESK</span> Real External ID sign-in · token-validated API · persistent supplier data</div><div class="vendor-experience-path" aria-label="Experience sequence"><span><b>01</b> Arrive</span><span><b>02</b> Sign up</span><span><b>03</b> Establish trust</span><span><b>04</b> Reach approved work</span></div><div class="vendor-portal"><header class="vendor-brand"><a href="#lena/experience" aria-label="Harborline vendor portal">H<span>ARBORLINE</span></a><span>VENDOR PORTAL</span><span class="vendor-brand-right">${scene==='workspace'?'Lena Fischer · sample view':'Your work. Your properties.'}</span></header>${scene==='welcome'?`<div class="vendor-welcome"><div class="vendor-welcome-copy"><span class="vendor-kicker">MEET LENA FISCHER</span><h2>One partner.<br>Two properties.<br><em>A simpler way in.</em></h2><p>Lena needs to coordinate work across Harbor View and Bayside. Her account opens the door; her approved vendor relationship determines what she can do.</p><div class="vendor-benefits"><span>Recognizable experience</span><span>Trusted business context</span><span>Application-enforced access</span></div></div><div class="vendor-entry"><div class="vendor-entry-badge">H</div><span class="vendor-kicker">BRANDED EXTERNAL ID JOURNEY</span><h3>Welcome to Harborline</h3><p>Use the connected application for real registration and sign-in. Explore the sample workspace to rehearse the business story and access boundary.</p>${liveLink('Open live Supplier Desk')}<button class="vendor-preview-button" data-vendor="preview">Preview the workshop workspace →</button><div class="vendor-entry-foot"><b>Returning vendor?</b> Account recovery takes place on the configured External ID sign-in page.</div></div></div>`:`<div class="vendor-workspace"><div class="vendor-workspace-heading"><div><span class="vendor-kicker">ILLUSTRATIVE VENDOR EXPERIENCE</span><h2>Hello, Lena.</h2><p>Your assigned properties and work, together.</p></div><button class="vendor-text-button" data-vendor="welcome">Back to welcome</button></div><div class="vendor-context"><div><small>Company</small><strong>Harborline Supply Co.</strong><span>Sample vendor organization</span></div><div><small>Property scope</small><strong>Harbor View + Bayside</strong><span>Example approved assignments</span></div><div><small>Role</small><strong>Vendor coordinator</strong><span>Illustrative application role</span></div></div><div class="vendor-orders-heading"><h3>Your work orders</h3><span>3 sample orders</span></div><div class="vendor-order-list">${orders.map(o=>`<button class="vendor-order" data-vendor="order" data-id="${o.id}"><span class="vendor-order-id">${o.id}<small>${o.property}</small></span><span class="vendor-order-title"><strong>${o.title}</strong><small>${o.area}</small></span><span class="vendor-order-status">${o.status}</span><span aria-hidden="true">↗</span></button>`).join('')}</div><div class="vendor-boundary"><strong>Why does Lena see these properties?</strong><p>In the real application, server-side permissions must use her trusted vendor assignment. This preview illustrates the result; it does not validate a token or enforce access.</p><a href="#lena/explain">Reveal the architecture →</a></div></div>`}</div>${selectedOrder?orderDialog():''}`;}
function orderDialog(){const o=orders.find(x=>x.id===selectedOrder);if(!o)return '';return `<dialog id="vendor-order-dialog" aria-labelledby="vendor-order-title"><div class="modal-header"><h2 id="vendor-order-title">${o.id} · ${e(o.property)}</h2><button class="quiet" data-vendor="close-order" aria-label="Close work order">✕</button></div><div class="modal-body"><span class="pill">Synthetic workshop order</span><h3>${e(o.title)}</h3><p>${e(o.detail)}</p><dl><dt>Current state</dt><dd>${e(o.status)}</dd><dt>Planning window</dt><dd>${e(o.due)}</dd></dl><p>Real access must be checked against this order’s vendor and property on the server.</p><button class="primary" data-vendor="close-order">Return to work orders</button></div></dialog>`;}
function explain(){const s=stages[explainIndex];return `${caseArchitecture(10)}<div class="vendor-explain-intro"><span class="vendor-kicker">EXPLAIN THE EXPERIENCE</span><h2>Identity opens the door.<br>Authorization defines the room.</h2><p>Select a stage to show what happens from Lena’s first visit through change, removal and evidence.</p></div><div class="vendor-flow" aria-label="Explore the identity flow">${stages.map((s,i)=>`<button data-vendor="flow" data-index="${i}" aria-pressed="${i===explainIndex}"><b>0${i+1}</b><strong>${s[0]}</strong>${i<stages.length-1?'<span aria-hidden="true">→</span>':''}</button>`).join('')}</div><div class="vendor-flow-detail"><span>STAGE 0${explainIndex+1} · ILLUSTRATIVE ARCHITECTURE</span><h3>${s[1]}</h3><p>${s[2]}</p></div><div class="vendor-explain-grid"><section><span class="vendor-kicker">OPTIONAL ENRICHMENT</span><h3>Bring business context into the journey</h3><p>A configured custom authentication extension can validate sign-up attributes or obtain claims from an external system. Any company or property entitlement must come from a trusted source.</p><a href="https://learn.microsoft.com/en-us/entra/identity-platform/custom-extension-overview" target="_blank" rel="noopener noreferrer">Microsoft extension reference ↗</a></section><section><span class="vendor-kicker">KEEP THE TWO TRACKS CLEAR</span><h3>Customer identity ≠ workforce collaboration</h3><p>Lena’s customer-facing application belongs in the external tenant. Workforce B2B access packages and access reviews remain in the workforce collaboration track.</p><a href="https://learn.microsoft.com/en-us/entra/external-id/external-identities-overview" target="_blank" rel="noopener noreferrer">Compare the tenant models ↗</a></section></div>`;}
function prove(){return `<div class="vendor-proof-head"><div><span class="vendor-kicker">PROVE THE OUTCOME</span><h2>Show the evidence behind the experience.</h2><p>This is a presenter checklist. Checks are manually recorded for this page session and are not live telemetry.</p></div><a class="outline" href="https://entra.microsoft.com/?tid=${vendorConfig.externalTenantId}" target="_blank" rel="noopener noreferrer">Open external tenant ↗</a></div><div class="vendor-evidence-list">${proof.map(([title,desc],i)=>`<label class="vendor-evidence"><input type="checkbox" data-vendor-proof="${i}" ${checked.has(i)?'checked':''}><span><strong>${title}</strong><small>${desc}</small></span><em>${checked.has(i)?'Presenter checked':'Not verified here'}</em></label>`).join('')}</div><div class="vendor-proof-summary" role="status">${checked.size} of ${proof.length} checks marked by presenter</div><section class="vendor-ai"><div><span class="vendor-kicker">HOW AI COULD HELP</span><h3>Turn scattered evidence into a review brief.</h3><p>An assistant could summarize supplied sign-in and application records, identify missing evidence and suggest the next diagnostic check. Operators verify the conclusion and approve changes.</p></div><details><summary>Show an example investigation prompt</summary><blockquote>“For Lena’s attempted sign-in, compare the supplied user, application, timestamp and result. Explain the observed failure, cite each supporting record, identify missing evidence and propose the next read-only check. Do not assume a successful sign-in proves work-order authorization.”</blockquote><p>Illustrative prompt. No tenant data is sent to an AI service from this page.</p></details></section>`;}
export function vendorPage(mode='experience'){view=['experience','explain','prove'].includes(mode)?mode:'experience';return `<div class="vendor-shell"><header class="vendor-topbar"><a href="#home"><img src="./assets/majorkey-logo.svg" alt="MajorKey" width="145" height="26"></a><span>MICROSOFT ENTRA EXTERNAL ID · LIVE SUPPLIER EXPERIENCE</span><a href="#home">← Choose a persona</a></header><main class="vendor-main"><section class="tenant-model-banner"><div><span>SELECTED IDENTITY MODEL</span><strong>External tenant</strong></div><p>Customer and business-customer applications · branded user flow · application and API authorization</p><a href="#home">Compare workforce journeys →</a></section><section class="external-hero"><div class="external-hero-copy"><span class="vendor-kicker">LENA FISCHER · VENDOR COORDINATOR</span><h1>From first visit<br>to <em>trusted access.</em></h1><p>Follow one external identity from a branded welcome through sign-up, business authorization, recovery and evidence.</p><div class="external-capabilities"><span>External tenant</span><span>Branded user flow</span><span>Application roles</span><span>Evidence &amp; recovery</span></div><div class="external-hero-actions">${view==='experience'?liveLink('Open live Supplier Desk'):'<a class="primary" href="#lena/experience">Begin the journey →</a>'}<button class="outline" data-vendor="desktop">Open protected desktop</button></div></div>${identityConstellation()}</section><nav class="vendor-modes" aria-label="Lena’s journey">${[['experience','01','Experience'],['explain','02','Architecture'],['prove','03','Evidence']].map(([id,num,label])=>`<a href="#lena/${id}" ${view===id?'aria-current="page"':''}><span>${num}</span>${label}</a>`).join('')}</nav><section class="demo-readiness-strip" aria-label="Demo readiness"><div><span>LIVE SUPPLIER DESK</span><strong>Connected</strong></div><div><span>PROTECTED ENTRA WORKSPACE</span><strong>Presenter sign-in</strong></div><div><span>TOKEN-VALIDATED API</span><strong>Connected</strong></div></section>${vendorJourney()}${view==='experience'?experience():view==='explain'?explain()+companyPlaybook('lena'):prove()}${vendorNarrative()}<footer class="vendor-footer"><span>Harborline · MajorKey identity workshop</span><span>Live connection: ${vendorConfig.livePortalUrl?'portal configured':'awaiting verified vendor application'}</span></footer></main></div>`;}
export function installVendorEvents(render,onDesktop){document.addEventListener('click',event=>{const button=event.target.closest('[data-vendor]');if(!button)return;const action=button.dataset.vendor;if(action==='desktop'){onDesktop();return;}if(action==='journey'){const i=Number(button.dataset.index);if(i<2){scene=i===0?'welcome':'workspace';location.hash='#lena/experience';}else if(i<7){explainIndex=i;location.hash='#lena/explain';}else location.hash='#lena/prove';render();return;}if(action==='preview')scene='workspace';if(action==='welcome')scene='welcome';if(action==='flow')explainIndex=Number(button.dataset.index);if(action==='order')selectedOrder=button.dataset.id;if(action==='close-order')selectedOrder=null;render();const dialog=document.querySelector('#vendor-order-dialog');if(dialog){dialog.addEventListener('cancel',()=>{selectedOrder=null;},{once:true});dialog.showModal();}else if(action==='close-order')document.querySelector('[data-vendor="order"]')?.focus();});document.addEventListener('change',event=>{if(!event.target.matches('[data-vendor-proof]'))return;const i=Number(event.target.dataset.vendorProof);event.target.checked?checked.add(i):checked.delete(i);render();document.querySelector(`[data-vendor-proof="${i}"]`)?.focus();});}
export function lenaGuide(){const step=(action,why,look)=>({action,why,look});return {company:companyStories.lena,name:'Lena Fischer',time:'Vendor journey',title:'From first visit to useful access.',job:'Vendor coordinator',perspective:'User view',story:'Lena needs to register, sign in and coordinate assigned work across properties.',why:'Connect a recognizable customer experience with verifiable identity and application controls.',account:'Confirm Lena’s existing local-account sign-in name',domain:'External tenant · verify in the administrator profile',cases:cases.filter(c=>[10,11,12,26,32].includes(c.id)),highlights:['Open the real vendor application','Show Lena’s sign-in and permitted work','Verify identity and application evidence'],admin:[step('Switch to external tenant 5b978a26-961f-40b9-877d-bfedaec7463d. Find the Vendor Portal registration and associated sign-up/sign-in user flow.','The customer flow is configured separately from the workforce tenant.','Verify application ID, redirect URI, flow association and enabled identity providers.'),step('Inspect branding, collected attributes and applicable authentication policies. Compare them with the actual sign-in experience.','Configuration must match what Lena sees.','Show only methods and policies present in the tenant; do not promise an unconfigured passkey or social sign-in.'),step('Inspect Lena’s sign-in event and application-side authorization evidence.','Authentication alone does not establish work-order permissions.','Match user, app and event time; test allowed and denied resource requests on the real API.')],user:[step('Open the live Harborline Supplier Desk in a separate persona browser profile inside the VM.','Keep Lena separate from the administrator session.','Use the connected supplier URL and confirm the browser returns to it after External ID sign-in.'),step('Use Lena’s existing local account, or deliberately register a separate prepared test identity through the configured flow.','Existing-user recovery and new-user registration are different journeys.','Use privately held credentials and the configured MFA method. No passwords are stored in the public workshop.'),step('Open an assigned work item, then observe an intentionally tested unauthorized resource request.','The business story needs a permission boundary enforced by the application.','Show the actual allowed result and server/API denial. The preview’s sample orders are not proof.'),step('For the local password account, demonstrate the configured password-recovery path when rehearsed and ready.','Self-service recovery lets Lena return to work.','A real completed recovery and subsequent sign-in, without displaying the password.')],userTitle:'Experience Lena’s vendor portal',evidence:'Correlate registration, authentication and application access with real records. Manually checked workshop steps are presenter notes only.',caution:'The Supplier Desk is connected. Verify its sign-in, token-protected API and prepared Lena data before each client session; the embedded workshop workspace remains illustrative.',question:'Where does your application determine which customer organization and resources a signed-in person may access?'};}
